 "decisions": [
  {
   "title": "Transaction boundary owned by the REST adapter",
   "context": "The legacy opens the transaction after the validations (line 108) and rolls back at three points, always rejecting with a non-zero status (50005, 50006, 50007).",
   "decision": "The program rejects with a non-zero status and no data, so the REST adapter owns the transaction and a business error undoes everything. No UnitOfWork port with begin/commit/rollback is declared. The rollbacks are declared in unit_of_work with the error code they reject with. There are no savepoints.",
   "consequences": "The validations and reads before the debit also run inside the transaction. They are read-only, so the outcome is the same. A rejection after the first debit also undoes the debit movement."
  },
  {
   "title": "Data moves to the target PostgreSQL database",
   "context": "data_strategy is migration. The four legacy tables (db_pagos..pg_orden, db_admin..ad_tarifa_empresa, db_admin..ad_servicio, db_cuentas..ct_cuenta) are migrated.",
   "decision": "Each table becomes an entity with a snake_case target table and columns and keeps the legacy precision (money -> decimal(19,4)). db_cuentas..sp_debito stays an external program behind the DebitGateway port. It is not reimplemented.",
   "consequences": "Debit movements are still produced by the account system. The payment and the debit share one atomic transaction only if the gateway participates in the same transaction. This must be confirmed at integration."
  },
  {
   "title": "Error exit and cobis..sp_cerror are infrastructure",
   "context": "The ERROR label calls cobis..sp_cerror and returns the error number. @@error checks are also plumbing.",
   "decision": "sp_cerror is not translated and is listed as infrastructure. The error code and message are carried by business exceptions mapped to the stable error codes. A technical failure of the debit call (legacy @@error <> 0) is treated like a non-zero return code and gives DEBIT_FAILED.",
   "consequences": "The legacy return value (the numeric error) is exposed through each error's legacy_code."
  },
  {
   "title": "Order of the checks and null semantics are preserved",
   "context": "The legacy validates in this order: account type, order exists, order pending, tariff, commission, total, funds. A missing account gives a null balance, so the funds comparison is not true and the legacy does not reject.",
   "decision": "The same order is kept. If the account is not found (Optional empty), the funds check does not reject and the debit step decides, as in the legacy. A null tariff becomes 0. A tariff row with a null separate-charge flag counts as not 'S', so the commission is added to the total.",
   "consequences": "Behaviour equals the legacy, including these edge cases."
  },
  {
   "title": "Commission arithmetic",
   "context": "WEB channel: round(tariff / 2, 2). Other channels pay the full tariff. NOMINA is always 0. The overdraft margin is a fixed 100.00 for non-VIR accounts.",
   "decision": "BigDecimal with scale 4 is used. Rounding to 2 decimals is HALF_UP (away from zero), as the legacy round() does. The channel default 'WEB' of the legacy parameter is applied when the channel is not sent.",
   "consequences": "Results match the golden master to 4 decimals. A different rounding mode would show up as a difference in the commission."
  }
 ],
