package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.CompanyTariff;
import com.bank.payments.domain.port.CompanyTariffRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/** JDBC adapter of the port CompanyTariffRepository (table company_tariff). */
@Repository
public class JdbcCompanyTariffRepository implements CompanyTariffRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcCompanyTariffRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<CompanyTariff> findByCompanyAndService(Integer companyId, String serviceCode) {
        List<CompanyTariff> rows = jdbcTemplate.query(
                "SELECT company_id, service_code, tariff_value, separate_charge "
                        + "FROM company_tariff WHERE company_id = ? AND service_code = ?",
                (rs, rowNum) -> new CompanyTariff(
                        rs.getObject("company_id", Integer.class),
                        rs.getString("service_code"),
                        rs.getBigDecimal("tariff_value"),
                        rs.getString("separate_charge")),
                companyId, serviceCode);
        return rows.stream().findFirst();
    }
}
